#include <vector>
#include <algorithm>

class Solution {
public:
    int minOperations(std::vector<int>& nums) {
        int cost0 = 0, cost1 = 0;
        for (int i = 0; i < (int)nums.size(); ++i) {
            int p = (nums[i] % 2 + 2) % 2;
            if (p != i % 2) cost0++;
            if (p != (i + 1) % 2) cost1++;
        }
        return std::min(cost0, cost1);
    }
};

class Solution {
    public int minOperations(int[] nums) {
        int cost0 = 0, cost1 = 0;
        for (int i = 0; i < nums.length; i++) {
            int p = (nums[i] % 2 + 2) % 2;
            if (p != i % 2) cost0++;
            if (p != (i + 1) % 2) cost1++;
        }
        return Math.min(cost0, cost1);
    }
}

